import{_ as d}from"./chunks/settings-cal.pc.ko.BDoJOykj.js";import{_ as o}from"./chunks/maintenance-pwr.pc.ko.DU4C6rG6.js";import{_ as c,o as t,c as a,a5 as r}from"./chunks/framework.D47SInms.js";const i="/RBQ/nightly/images/app/settings-chk.pc.ko.png",l="/RBQ/nightly/images/app/maintenance-vision.pc.ko.png",n="/RBQ/nightly/images/app/maintenance-ini.pc.ko.png",_=JSON.parse('{"title":"정비","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/maintenance.md","filePath":"ko/manual/gui/maintenance.md","lastUpdated":1791600043000}'),h={name:"ko/manual/gui/maintenance.md"};function p(s,e,m,b,u,g){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="정비" tabindex="-1">정비 <a class="header-anchor" href="#정비" aria-label="Permalink to &quot;정비&quot;">​</a></h1><p>허브의 <code>정비</code> 타일로 엽니다. 타일은 모든 사용자에게 보이고 로봇이 연결되지 않아도 열립니다. 로봇에 작용하는 섹션은 연결돼 있어야 동작합니다. 섹션은 화면 위쪽에 칩으로 늘어섭니다.</p><ul><li><strong>모든 사용자:</strong> <code>캘리브레이션</code>, <code>로봇 점검</code>, <code>소프트웨어 업데이트</code>(<a href="/RBQ/nightly/ko/manual/gui/software-update.html">소프트웨어 업데이트</a>에서 다룹니다), <code>펌웨어 업데이트</code>.</li><li><strong><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a> 전용:</strong> <code>전원 / 시스템</code>, <code>비전</code>, <code>설정 파일</code>, 그리고 팔이 있는 로봇에서만 보이는 <code>팔</code>. 이 섹션의 조작은 연결을 끊거나 로봇을 주저앉히거나 데몬 기동 방식을 바꿉니다 — 누르기 전에 각 경고를 읽으세요.</li></ul><h2 id="calibration" tabindex="-1">캘리브레이션 <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;캘리브레이션 {#calibration}&quot;">​</a></h2><p><img src="'+d+'" alt="캘리브레이션 섹션"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>여기의 모든 보정은 로봇을 평지에 <strong>정지</strong> 상태로 두고 실행해야 합니다. 로봇이 걷고 있거나 넘어졌거나 상태를 보내지 않으면 IMU·ZMP 행이 막힙니다. 명령을 보내기 전에는 <code>보정을 실행할까요?</code> 확인이 먼저 뜹니다. 관절 홈포즈 세팅은 확인 창을 따로 씁니다. 보정이 끝날 때까지 로봇을 건드리지 마세요.</p></div><h3 id="imu-캘리브레이션" tabindex="-1">IMU 캘리브레이션 <a class="header-anchor" href="#imu-캘리브레이션" aria-label="Permalink to &quot;IMU 캘리브레이션&quot;">​</a></h3><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>가속도계 보정 (ACC)</code></td><td>가속도계 드리프트를 현장에서 보정합니다. <strong>로봇을 앉힌 상태로</strong> 평지에 두고 실행하며, 약 2초 동안 중력 크기를 평균 내 보정계수를 저장합니다.</td></tr><tr><td><code>IMU 롤/피치 영점</code></td><td>현재 자세를 수평 기준으로 삼습니다. 약 0.5초 — 기울어진 상태로 실행하면 이후 제어가 전부 틀어집니다.</td></tr><tr><td><code>자이로 바이어스 보정</code></td><td>IMU를 리셋하고 값이 자리 잡기를 기다린 뒤 자이로 값을 다시 측정합니다. 약 5초, <strong>로봇을 앉힌 상태로</strong> 실행합니다. 끝나면 세 축의 값과 각 축이 허용치 안에 드는지를 알려 줍니다. 그래도 편차가 허용치를 넘으면 로봇을 완전히 멈춰 둔 채로 다시 실행하십시오.</td></tr></tbody></table><p><code>실행</code>을 누른 뒤 대화상자에서 <code>실행</code>으로 확정합니다. 막혀 있으면 이유를 알려 주고, 앱이 직접 풀 수 있는 것이면 <code>실행</code> 옆에 버튼이 하나 생깁니다 — 앉아야 하면 <code>앉기</code>, 서야 하면 <code>서기</code>, 제어가 꺼져 있으면 <code>자동 기동</code>입니다(이 버튼은 확인 창이 먼저 뜹니다). 넘어졌거나 도킹 중이거나 상태가 오지 않을 때는 버튼이 나오지 않습니다.</p><p><code>IMU 롤/피치 영점</code>은 확인 창의 수평계 아래에 현재 롤·피치를 보여 주고, 실행하는 동안 진행 창이 뜹니다. 롤·피치가 모두 1° 안으로 들어왔을 때만 <code>성공</code>으로 끝나고, 로봇이 아직 기울어 있으면 <code>영점이 반영되지 않았을 수 있습니다</code> 가 대신 뜹니다 — 평지에 두고 다시 실행하십시오.</p><h3 id="무게-중심-보정-zmp" tabindex="-1">무게 중심 보정 (ZMP) <a class="header-anchor" href="#무게-중심-보정-zmp" aria-label="Permalink to &quot;무게 중심 보정 (ZMP)&quot;">​</a></h3><p><code>무게 중심 오프셋 자동 보정</code>은 무게중심 오프셋을 자동으로 찾습니다. 로봇이 평지에서 STAND 상태여야 합니다. 다리를 나란히 맞추려고 한 걸음 걸은 뒤, 수렴할 때까지 최대 60초가 걸립니다. 오프셋이 수렴하면 로봇이 스스로 저장하고 STAND로 돌아옵니다. 패널에 진행 상황과 완료 메시지가 표시됩니다.</p><h3 id="관절-캘리브레이션" tabindex="-1">관절 캘리브레이션 <a class="header-anchor" href="#관절-캘리브레이션" aria-label="Permalink to &quot;관절 캘리브레이션&quot;">​</a></h3><p>다리 관절의 영점·오프셋을 다시 잡습니다. 로봇을 <strong>앉힌 상태</strong>로 실행합니다.</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>관절 홈포즈 세팅</code></td><td>치구로 홈 자세를 고정한 뒤 그 자세를 관절 영점으로 저장 — 다리 4개</td></tr><tr><td><code>DQ 오프셋 보정</code></td><td><code>준비 중</code> — 자리만 잡혀 있고 누를 수 없습니다</td></tr></tbody></table><p><code>관절 홈포즈 세팅</code>을 누르면 창이 둘 열립니다. 먼저 고지(<em>관절 영점을 다시 쓰는 조작입니다 — 치구가 없거나 자세가 어긋난 상태로 실행하면 로봇이 잘못된 영점으로 기동합니다</em>), 그다음 다리별 화면입니다. 그 화면에서 관절 카드를 누르면 그 관절이 왼쪽 3D 뷰에서 목표 자세까지 움직입니다. 치구를 끼워 그 자세를 만든 뒤 그 카드의 <code>LEG{n} - {g} 홈포즈 저장</code>을 누릅니다. 롤 카드와 피치·무릎 카드에 버튼이 따로 있습니다. 영점을 쓰는 순간 제어가 꺼지므로(BOARD_RESET) 로봇을 먼저 앉히십시오. 서 있으면 그대로 주저앉습니다. 치구가 필요합니다.</p><p>모터 보드와 통신이 없으면 행이 막히고 <em>모터 보드와 통신이 없습니다 — 48V 구동(LEGS) 전원을 켠 뒤 다시 실행하세요.</em> 가 뜹니다. 그 레일은 이 페이지의 <a href="#power">전원 / 시스템</a>에 있습니다.</p><p>롤 관절은 마법사에서 기준을 고릅니다. <code>리밋</code>은 종전처럼 안쪽 리밋에 갖다 대고 잡고, <code>수평계 0°</code>는 몸통이 수평인지 확인한 뒤 수평계로 관절을 0°에 맞추고, 영점을 그에 맞게 옮깁니다. 두 기준 모두 제어를 끕니다. 닫을 때 <code>자동 기동</code> 버튼으로 바로 다시 기동할 수 있습니다. 보정량이 9° 이상이면 로봇이 거부하고, 먼저 리밋에 대고 홈을 잡으라고 안내합니다.</p><h3 id="camera-check" tabindex="-1">카메라 점검 · 보정 <a class="header-anchor" href="#camera-check" aria-label="Permalink to &quot;카메라 점검 · 보정 {#camera-check}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>카메라 기본 검사</code></td><td>카메라 6대의 화면과 FPS 를 띄웁니다. 화면 연결은 아직 준비 중입니다.</td></tr><tr><td><code>하단 depth 카메라 On-chip 캘리브레이션</code></td><td>하단 depth 카메라의 On-chip 보정 안내를 띄웁니다. 로봇을 평평한 바닥에 세워 두세요. 보정 시퀀스는 아직 준비 중입니다.</td></tr><tr><td><code>하단 depth 카메라 위치 보정</code></td><td>로봇 하단에 마커보드를 설치하라는 안내를 띄웁니다. 보정 자체는 아직 준비 중입니다.</td></tr></tbody></table><h3 id="도킹-캘리브레이션" tabindex="-1">도킹 캘리브레이션 <a class="header-anchor" href="#도킹-캘리브레이션" aria-label="Permalink to &quot;도킹 캘리브레이션&quot;">​</a></h3><p>캘리브레이션 섹션 맨 아래에 자동 도킹 정렬 파라미터가 있습니다: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>다시 읽기</code> — 로봇에서 값을 다시 읽어옵니다.</li><li><code>기본값</code> — 입력칸을 출고 기본값으로 채웁니다. <code>적용</code>을 누르기 전에는 저장되지 않습니다.</li><li><code>적용</code> — 값을 로봇에 저장하고 다시 읽어 확인합니다.</li></ul><h2 id="robot-check" tabindex="-1">로봇 점검 <a class="header-anchor" href="#robot-check" aria-label="Permalink to &quot;로봇 점검 {#robot-check}&quot;">​</a></h2><p><img src="'+i+'" alt="로봇 점검 섹션"></p><p><code>로봇 점검</code>은 앉은 자세부터 걷기까지 로봇 상태를 순서대로 점검합니다. 단계마다 카드가 있고, <code>측정</code>을 누른 뒤 결과를 보고, 기준을 벗어나면 옆의 보정 버튼으로 그 자리에서 고칩니다. 보정 버튼은 측정 결과와 상관없이 로봇 상태만 맞으면 누를 수 있습니다. 기준을 벗어난 값은 카드에 <code>주의</code>로만 표시됩니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>4·5단계는 로봇이 스스로 움직이며, 그동안 조이스틱 입력은 무시됩니다. 시작하기 전에 로봇 주변 1 m 를 비우세요. <code>중지</code>를 누르면 점검을 멈추고 로봇이 섭니다.</p></div><h3 id="보행-점검" tabindex="-1">보행 점검 <a class="header-anchor" href="#보행-점검" aria-label="Permalink to &quot;보행 점검&quot;">​</a></h3><table tabindex="0"><thead><tr><th>단계</th><th>로봇</th><th>측정</th><th>기준</th><th>보정</th></tr></thead><tbody><tr><td>1 <code>앉음 · IMU</code></td><td>앉음</td><td>중력 크기와 자이로 편차 3초 평균</td><td>9.75 ~ 9.85 m/s², 자이로 1.0 °/s 미만</td><td><code>가속도계 보정</code>, <code>자이로 바이어스 보정</code></td></tr><tr><td>2 <code>모터 캘리브레이션 상태</code></td><td>앉음</td><td>추후 지원 예정입니다</td><td>—</td><td>—</td></tr><tr><td>3 <code>서기 · 수평</code></td><td>섬</td><td>몸통 위에 올린 물방울 수평계로 몸통을 손으로 맞춘 뒤 롤·피치 2초 평균</td><td>±0.3°</td><td><code>IMU 롤/피치 영점</code></td></tr><tr><td>4 <code>관절 통신 상태</code></td><td>섬</td><td>몸통을 좌우 최대 30°로 5번(약 10초) 비트는 동안 CAN 통신 — <code>모터별</code>: 누락 프레임 수, 최저 수신 주파수, 최대 수신 간격 / <code>채널별</code>: <code>에러 프레임</code>, <code>error-warning</code>, <code>error-passive</code>, <code>bus-off</code></td><td>수신 450 Hz 이상, 수신 간격 10 ms 이하</td><td>—</td></tr><tr><td>5 <code>제자리 걸음 · 밀림</code></td><td>섬</td><td>제자리에서 10초 걸은 뒤 다시 서서 시작 위치와 비교</td><td>앞뒤 ±10 cm 미만, 좌우 ±5 cm 미만</td><td><code>육안검사</code> → <code>관절 홈포즈 세팅</code> → <code>무게 중심 보정</code></td></tr></tbody></table><ul><li>4단계: 기준을 벗어난 관절이 있으면 카드에 그 다리가 표시되고, 몸통과 그 다리 모듈 사이의 배선을 점검하라고 안내합니다. 관절끼리 누락 프레임을 비교하세요. 다른 관절은 괜찮은데 한 관절만 누락이 생기면 그 다리의 배선을 의심할 수 있습니다. <code>채널별</code>에는 다리가 붙은 CAN 채널이 그 채널의 다리와 함께 나옵니다. <code>에러 프레임</code>은 트위스트 동안 채널이 상태 변화(error-warning, error-passive, bus-off, 복귀)를 알린 횟수입니다. 이 숫자들은 참고용이며 판정에는 쓰지 않습니다. 시뮬은 CAN 계측이 없어 판정하지 않습니다.</li><li>5단계: 앞뒤로 10 cm 이상 또는 좌우로 5 cm 이상 밀리면 카드에 밀린 방향이 모두 표시되고, <code>육안검사</code> → <code>관절 홈포즈 세팅</code> → <code>무게 중심 보정</code> 순서로 진행하라고 안내합니다. 홈포즈 세팅은 캘리브레이션의 다리 마법사와 같고 앉은 상태에서만 할 수 있어, 서 있으면 <code>앉기</code> 버튼이 먼저 나옵니다.</li></ul><h3 id="카메라-점검" tabindex="-1">카메라 점검 <a class="header-anchor" href="#카메라-점검" aria-label="Permalink to &quot;카메라 점검&quot;">​</a></h3><p><code>카메라 시야 · FPS</code>, <code>depth 카메라 품질</code>, <code>depth 카메라 위치 정합</code> 세 단계가 있습니다. 측정·판정은 아직 준비 중이며, 보정 버튼은 <a href="#camera-check">캘리브레이션 › 카메라 점검 · 보정</a>과 같은 창을 엽니다.</p><h2 id="board-firmware" tabindex="-1">펌웨어 업데이트 <a class="header-anchor" href="#board-firmware" aria-label="Permalink to &quot;펌웨어 업데이트 {#board-firmware}&quot;">​</a></h2><p><code>펌웨어 업데이트</code>는 로봇 안에 있는 보드(다리 모터 16개, PDU, IF, SIDE_F, SIDE_H, TOP)의 펌웨어를 로봇에 들어 있는 최신 파일로 올립니다. 로봇 PC의 소프트웨어를 바꾸는 <code>소프트웨어 업데이트</code>와는 다른 섹션입니다. 보드마다 어느 파일을 쓸지는 로봇이 그 보드의 hw를 읽고 정합니다. 로봇에 그 종류의 펌웨어 파일이 hw를 이름에 단 것으로 하나도 없으면 그 보드는 <code>대상 아님</code>으로 두고 건너뜁니다.</p><p>다리 모터 16개는 모두 같은 펌웨어여야 하므로 묶음 하나로 봅니다. 화면의 수와 목록에서도 모터는 한 항목(<code>모터(n개)</code>)입니다. 버전이 같아도 파일과 내용이 다른 모터는 다시 굽고, 모터끼리 펌웨어가 다르면 위쪽에 배너가 뜹니다. 모터를 올리는 중에 한 장이라도 올릴 수 없으면(동의하지 않은 다운그레이드 등) 로봇은 모터를 하나도 굽지 않고 이유를 알려 줍니다.</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>상태</code></td><td>보드 수를 <code>업데이트 가능</code> · <code>최신</code> · <code>확인 필요</code>로 나눠 보여 줍니다. 모터 묶음은 하나로 셉니다. 답하지 않는 보드는 <code>응답 없음</code>, 건너뛰는 보드는 <code>대상 아님</code>으로 따로 셉니다. <code>버전 확인</code>을 누르면 로봇이 보드마다 버전과 hw를 다시 읽습니다. 로봇이 서 있거나 걷는 동안에는 누를 수 없습니다.</td></tr><tr><td><code>전체 업데이트</code></td><td>올릴 보드를 PDU → IF → SIDE_F → SIDE_H → TOP → 다리 모터 순서로 하나씩 올립니다. 누르면 확인 창부터 뜹니다.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>전체 업데이트는 다리·팔 전원을 끄고 진행하며, 끝나도 다리·팔 전원은 꺼진 채로 남습니다. 끝나면 로봇을 다시 기동하세요. 다리 모터를 올릴 때만 다리 전원을 잠시 켭니다. PDU를 올리는 동안 UPC 전원이, TOP을 올리는 동안 12V 포트가 잠시 꺼집니다. 로봇이 앉아 있거나 제어가 꺼져 있을 때만 시작할 수 있고, 관절에 제어가 들어가 있으면 앉아 있을 때만 시작할 수 있습니다. 비상정지가 걸린 뒤라도 다리 전원이 꺼져 있으면 시작할 수 있습니다(hw 기록이 없는 TOP 은 비상정지를 걸어 둡니다).</p></div><p><code>전체 업데이트</code>를 누를 수 없으면 그 행 아래에 이유가 나옵니다.</p><ul><li><code>구동 중입니다 — 로봇을 앉힌 뒤 다시 시도하세요</code> — 로봇이 서 있거나 걷고 있습니다. 관절에 제어가 들어가 있는데 로봇이 앉아 있지 않을 때(자동 기동 중 등)도 이 이유가 나옵니다.</li><li><code>다른 기기가 조종 중입니다</code> — 다른 기기가 조종권을 쥐고 있습니다.</li><li><code>확인이 필요한 보드가 있습니다</code> — 로봇에 그 보드에 맞는 파일이 없거나, 보드의 hw를 몰라 파일을 정할 수 없습니다. 보드 이름과 이유가 함께 나옵니다. 이런 보드가 하나라도 있으면 전체 업데이트를 하지 않습니다.</li><li><code>업데이트할 보드가 없습니다</code> — 모든 보드가 최신이거나 <code>대상 아님</code>입니다.</li><li><code>로봇이 펌웨어 작업을 하는 중입니다 — 끝난 뒤 다시 시도하세요</code> — 로봇이 다른 펌웨어 작업을 하고 있습니다.</li><li><code>로봇 소프트웨어가 이 기능을 지원하지 않습니다 — 소프트웨어 업데이트를 먼저 하세요</code></li></ul><p>부트 상태에 남은 보드는 hw를 몰라도 막지 않습니다. 업데이트하면 로봇이 그 보드를 앱으로 보내 hw를 다시 읽은 뒤 맞는 파일로 올립니다. 다리 전원이 꺼져 모터가 하나도 답하지 않을 때도 막지 않습니다. 이때는 로봇이 업데이트하면서 다리 전원을 켜고 모터를 확인합니다.</p><p>확인 창 하나에 올릴 보드와 동의할 내용이 모두 나옵니다. 다리나 팔에 제어가 들어가 있으면 전원을 내리고 진행한다는 문장이 붙고, 버튼이 <code>전원 내리고 업데이트</code>로 바뀝니다. 보드에 있는 것보다 낮은 버전으로 내려가는 보드가 있으면 그 보드와 두 버전이 적히고(모터는 한 줄로 묶어서), 다른 변형의 펌웨어가 돌던 보드는 맞는 변형으로 바꾼다는 문장이 붙습니다. 다리 전원이 꺼진 채 확인했다면 모터의 판정을 몰라 모터 다운그레이드에는 동의할 수 없습니다. 모터를 내려야 하면 다리 전원을 켠 채 <code>버전 확인</code>을 다시 누르세요. 창을 연 뒤 로봇의 확인 결과가 바뀌면 업데이트를 보내지 않고 바뀐 내용으로 다시 묻습니다.</p><p>진행하는 동안에는 같은 자리에 단계 목록(<code>48V 끄기</code>, 보드 이름, <code>다리 켜기</code>, <code>모터</code>, <code>다리 끄기</code>)이 나옵니다. 지금 올리는 보드에는 진행 막대가 붙고, 다시 보내는 중이면 <code>재시도 1/3</code>처럼 횟수가 나옵니다. 중간에 멈추는 버튼은 없고, 이 화면을 닫아도 로봇에서 계속 진행됩니다. 끝나면 <code>업데이트 완료 — 보드 n개</code>와 함께 전원이 꺼진 채라는 안내가 나옵니다. 실패하면 이유가 나오고 로봇은 다리 전원을 끈 채 멈춥니다. 보드 전송이 실패하면 로봇은 처음 전송 뒤 세 번까지 다시 보내 보고, 그래도 안 되면 그 보드를 부트 상태로 두고 멈춥니다. 잠시 뒤 다시 업데이트하세요.</p><h3 id="board-firmware-banner" tabindex="-1">상단 배너 <a class="header-anchor" href="#board-firmware-banner" aria-label="Permalink to &quot;상단 배너 {#board-firmware-banner}&quot;">​</a></h3><p>허브와 다른 화면 위쪽에 다음 배너가 뜰 수 있습니다.</p><ul><li><code>펌웨어 업데이트가 필요한 보드가 있습니다 (IF)</code> — 부트 상태에 남은 보드가 있거나, 그 보드의 hw를 지원하지 않는 펌웨어가 올라가 보드가 대기하고 있습니다. <code>열기</code>를 누르면 이 섹션으로 옵니다.</li><li><code>모터 펌웨어가 섞여 있습니다 — 펌웨어 업데이트를 하세요</code> — 모터끼리 펌웨어 버전이나 판정이 다릅니다. <code>열기</code>를 누르면 이 섹션으로 옵니다.</li><li><code>hw 기록이 필요한 보드가 있습니다 — 관리자 문의</code> — 보드에 hw가 기록되어 있지 않아 대기하고 있습니다. 업데이트로는 풀리지 않습니다.</li><li><code>EEPROM이 응답하지 않아 대기 중인 보드가 있습니다 — 관리자 문의</code> — 보드가 hw를 읽지 못해 대기하고 있습니다. 업데이트로는 풀리지 않습니다.</li></ul><p>배너 오른쪽의 X로 닫을 수 있습니다. 다른 보드가 걸리거나 로봇에 다시 연결하면 다시 뜹니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#board-firmware">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="power" tabindex="-1">전원 / 시스템 <a class="header-anchor" href="#power" aria-label="Permalink to &quot;전원 / 시스템 {#power}&quot;">​</a></h2><p><img src="'+o+'" alt="전원 / 시스템 섹션"></p><p>설정에서 일부러 뺀 레일까지 모든 PDU 레일이 여기 있습니다. 토글은 로봇이 보고한 실제 레일 상태를 표시하며, 상태를 받기 전에는 비활성화됩니다.</p><p><strong>12 V 토글</strong>(한 번 탭): <code>스피커 앰프 (12V)</code>, <code>LiDAR (12V)</code>, <code>CCTV (12V)</code>, <code>열화상 (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>끄면 연결이 끊기는 레일</strong>(2단계 확인 <code>정말 끌까요?</code> → <code>끄기</code>. 확인 창에 <code>하루 동안 묻지 않음</code> 체크박스가 있으며, 체크하면 이 화면에서만 해당 레일을 24시간 동안 확인 없이 전환합니다. 설정 → 전원 제어는 항상 확인합니다):</p><table tabindex="0"><thead><tr><th>레일</th><th>끄면</th></tr></thead><tbody><tr><td><code>카메라 (5V)</code></td><td>영상이 끊깁니다.</td></tr><tr><td><code>오디오·USB 허브 (5V)</code></td><td>오디오 장치가 사라집니다.</td></tr><tr><td><code>Vision PC (12V)</code></td><td>카메라·오디오와 이 화면의 텔레메트리 일부가 끊깁니다.</td></tr><tr><td><code>통신 (12V)</code></td><td>이 앱과 로봇의 연결 자체가 끊깁니다.</td></tr></tbody></table><p><strong>48 V 구동 레일</strong>(2단계, 현재 전압 표시):</p><table tabindex="0"><thead><tr><th>레일</th><th>비고</th></tr></thead><tbody><tr><td><code>LEGS (48V 구동)</code></td><td>다리 모터 전원. 로봇이 서 있지 않을 때(앉음·제어 꺼짐·낙상)만 끌 수 있으며, 그 외에는 행이 차단됩니다.</td></tr><tr><td><code>ARM · ADDON (48V)</code></td><td>팔과 애드온 전원 — 포트 하나를 함께 씁니다. 팔이 정지 상태인지 먼저 확인하세요.</td></tr><tr><td><code>EXTERN (48V)</code></td><td>외부 확장 포트 전원.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>LEGS (48V 구동)</code>을 끄면 로봇이 주저앉습니다. <code>시스템 재부팅</code> — <code>재부팅</code> → <code>로봇 PC를 재부팅할까요?</code> → <code>재부팅</code> — 은 로봇 PC를 재시작합니다. 그동안 로봇은 모터 전원을 잃고 앱 연결이 끊깁니다. 두 조작 모두 로봇을 바닥에 앉힌 뒤에 하세요. 재부팅 확인 창에도 <code>하루 동안 묻지 않음</code> 체크박스가 있습니다.</p></div><p>CAN-FD 기체에서는 위 레일 대신 PDU 포트가 <code>12V 포트</code>, <code>카메라 전원 (USB)</code>, <code>오디오</code>, <code>⚠ 48V 구동 레일 — 위험 조작</code> 네 묶음으로 개별 표시되며, 각 행에 실측 상태·전압·전류가 나옵니다. <code>통신 (12V · WAN)</code>, 카메라 포트, 48 V 포트는 2단계 확인이고, <code>LEGS (48V 구동)</code>은 위와 같이 서 있는 동안 차단되며, <code>PDU (48V 배터리 레일)</code>은 표시만 합니다. 아래 <code>입력 포트 · 배터리 · 온도</code>에 충전 입력, 배터리 두 팩, 보드 온도가 나옵니다. <code>오디오</code>와 48 V 묶음 사이의 <code>하단 상태 LED (IF 보드)</code>는 <a href="/RBQ/nightly/ko/manual/gui/settings.html#power">설정 › 전원 제어</a>와 같고, 개발자 모드에서 그 창에 늘어나는 것은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#what-changes">개발자 모드</a>에 있습니다.</p><p>48 V 레일 아래에는 <a href="#calibration">정비 → 캘리브레이션</a>에서 설명한 <code>가속도계 보정 (ACC)</code>과 <code>IMU 롤/피치 영점</code> 행이 한 번 더 있으며, 동작은 동일합니다.</p><h2 id="비전" tabindex="-1">비전 <a class="header-anchor" href="#비전" aria-label="Permalink to &quot;비전&quot;">​</a></h2><p><img src="'+l+'" alt="비전 섹션"></p><p>야간 모드·스텔스·IR 프로젝터·영상 해상도 같은 비전 토글은 제어 화면의 <code>비전</code> 팝오버에 있습니다. <a href="/RBQ/nightly/ko/manual/gui/camera-vision.html">카메라 · 비전</a>을 보세요. 이 섹션에는 개발자용 도구가 있습니다.</p><p><code>카메라 캘리브레이션</code>:</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>Jig Extrinsic 보정</code></td><td>지그 마커로 센서마다 base↔센서 변환을 보정합니다. 로봇이 캘리브 지그에 올바르게 안착되어 있어야 합니다. 결과는 HAL 설정에 기록됩니다.</td></tr><tr><td><code>OAK-D Intrinsic 보정</code></td><td>걸으면서 전방·후방 스테레오 카메라를 보정합니다. 전방 카메라가 1 m 이내에서 ChArUco 보드를 향해야 합니다. 결과는 각 카메라의 EEPROM 에 기록됩니다.</td></tr></tbody></table><p><code>실행</code>을 누르면 시작 전에 확인할 것을 보여 주는 창이 뜨고, 진행 상황과 결과는 상단 배너에 나옵니다. 보정이 도는 동안에는 두 버튼이 <code>취소</code>로 바뀝니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>OAK-D 내부 파라미터 보정은 로봇이 약 10분간 스스로 걸어 다닙니다. 시작하기 전에 로봇 주변 1.5 m 를 비우세요.</p></div><p><code>데몬 제어</code> — <code>VISION RESET</code> → <code>리셋</code>은 Handler가 HAL을 재시작해 카메라 파이프라인을 깨끗하게 재시작합니다. 영상이 수 초 끊기며, 버튼은 <code>리셋 중…</code>으로 바뀌어 약 8초 동안 비활성화됩니다.</p><p><code>Vision Programs</code>에서는 비전 데몬(<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Cctv</code>, <code>Ptz</code>, <code>Thermal</code>)을 하나씩 수동으로 시작·정지할 수 있습니다. 켜짐/꺼짐 표시는 로봇이 보고한 프로그램 상태를 따르며, 상태를 보고하지 않는 구형 데몬에서만 마지막으로 보낸 명령 기준으로 표시합니다.</p><h2 id="설정-파일" tabindex="-1">설정 파일 <a class="header-anchor" href="#설정-파일" aria-label="Permalink to &quot;설정 파일&quot;">​</a></h2><p><img src="'+n+'" alt="설정 파일 섹션"></p><p>INI 에디터는 로봇 데몬의 설정 파일을 직접 편집합니다. 대상 선택기로 <code>Motion.ini</code>, <code>HAL · config.ini</code>, <code>Handler · config.ini</code>, <code>Streamer.ini</code>를 전환합니다. <code>키 검색</code>으로 키를 필터링하고, 불리언 값은 토글로, 나머지 값은 그 자리에서 편집합니다. 헤더에는 읽어 온 섹션 수와 시각이 표시됩니다.</p><p>하단에 저장하지 않은 변경 수(<code>변경 {n}개</code>)가 표시됩니다. <code>되돌리기</code>는 변경을 버리고, <code>다시 읽기</code>는 로봇에서 파일을 다시 읽어오며, <code>저장</code>은 바뀐 키마다 이전 값과 새 값을 나열하는 확인 창 <code>{label}에 저장하시겠습니까?</code>을 엽니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>저장하면 로봇의 파일 <strong>전체</strong>가 에디터의 내용으로 교체됩니다. 항상 방금 읽어 온 파일 위에서 편집하세요. 변경은 해당 데몬(Motion, HAL, Handler, Streamer)을 재시작해야 반영되며, 앱이 대신 재시작하지 않습니다. 의미를 모르는 값은 바꾸지 마세요.</p></div><h2 id="팔" tabindex="-1">팔 <a class="header-anchor" href="#팔" aria-label="Permalink to &quot;팔&quot;">​</a></h2><p>로봇이 팔을 보고할 때만 표시됩니다. 이 섹션은 최초 기동용입니다.</p><ol><li><code>CAN 체크</code>, <code>브레이크 해제</code>, <code>제어 시작</code>을 순서대로 누릅니다. 각 단계 후 상태 배지가 켜지는 것을 확인한 뒤 다음을 누르세요. ▶ Auto Start ARM은 이 시퀀스 전체를 한 번에 실행합니다.</li><li><code>정적 자세</code>는 궤적 없이 고정 자세(<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>)를 보냅니다. 첫 사용은 <code>Ready</code>부터 시작하세요.</li><li><code>관절 잠금 / 조그</code> — 관절 카드를 탭해 잠금/해제하고, 잠긴 관절은 <code>+</code> / <code>−</code>를 길게 눌러 조그합니다(잠금 해제 상태에서는 버튼이 비활성화됩니다).</li></ol><p>RC01 / RC02 부착물 섹션은 이 매뉴얼에서 다루지 않습니다.</p>',76)])])}const q=c(h,[["render",p]]);export{_ as __pageData,q as default};
